+import { inputToRecipient, splitBySeparator } from '@proton/shared/lib/mail/recipient';
+
+describe('splitBySeparator', () => {
+    it('splits mixed separators in order and discards empty tokens', () => {
+        expect(splitBySeparator(',plus@debye.proton.black, visionary@debye.proton.black; pro@debye.proton.black,')).toEqual([
+            'plus@debye.proton.black',
+            'visionary@debye.proton.black',
+            'pro@debye.proton.black',
+        ]);
+        expect(splitBySeparator(' ; , < > ; ')).toEqual([]);
+    });
+
+    it('removes brackets and trims each token', () => {
+        expect(splitBySeparator(' <one@example.com> ; <<two@example.com>> ')).toEqual([
+            'one@example.com',
+            'two@example.com',
+        ]);
+    });
+});
+
+describe('inputToRecipient', () => {
+    it('uses the email as both name and address', () => {
+        expect(inputToRecipient('email@domain')).toEqual({ Name: 'email@domain', Address: 'email@domain' });
+        expect(inputToRecipient(' <email@domain> ')).toEqual({ Name: 'email@domain', Address: 'email@domain' });
+    });
+});
